export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const fmt=(n,d=1)=>Number.isFinite(n)?n.toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
export function downloadFile(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export const source=r=>r?.source_kind==='bundled-openfast'?'内置真实算例':r?.source_kind==='local-openfast'?'本机 OpenFAST':'导入结果 · 待核验';
export function pageShell(id,title,english,subtitle,actions){const page=document.getElementById('page-'+id),legacy=document.createElement('div');legacy.hidden=true;legacy.className='ow-legacy';legacy.append(...page.childNodes);page.replaceChildren(legacy);page.classList.add('ocean-workspace','ow-'+id);const root=document.createElement('div');root.className='ow-content';root.innerHTML=`<header class="ow-heading"><div><span class="ow-eyebrow">${english}</span><h1>${title}</h1><p>${subtitle}</p></div><div class="ow-header-actions">${actions}</div></header>`;page.append(root);return {page,root};}
